```javascript
import { Group, Mesh, PlaneGeometry, Color } from 'three/webgpu';
import { MeshBasicNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import { uniform, mix, uv, vec3, smoothstep, time } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const group = new Group();

  const colors = config.intent?.visualSpec?.colors ?? config.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const ink = new THREE.Color(colors.ink);
  const paper = new THREE.Color(colors.paper);
  const accent = new THREE.Color(colors.accent);
  const surface = new THREE.Color(colors.surface);

  // --- Backdrop gradient plane (STAGE rule) ---
  const backdropMat = new MeshBasicNodeMaterial();
  backdropMat.transparent = true;

  const topColor = uniform(vec3(surface.r, surface.g, surface.b));
  const midColor = uniform(vec3(ink.r * 0.6, ink.g * 0.6, ink.b * 0.6));
  const bottomColor = uniform(vec3(0.04, 0.04, 0.06));

  const vy = uv().y;
  const gradTop = mix(midColor, topColor, smoothstep(0.5, 1.0, vy));
  const gradFull = mix(bottomColor, gradTop, smoothstep(0.0, 0.5, vy));

  // Subtle accent glow at bottom for depth
  const accentGlow = mix(
    vec3(accent.r * 0.15, accent.g * 0.15, accent.b * 0.15),
    gradFull,
    smoothstep(0.0, 0.25, vy)
  );

  backdropMat.colorNode = accentGlow;

  const backdrop = new Mesh(new PlaneGeometry(7.2, 6.2), backdropMat);
  backdrop.position.set(0, 0, -2.5);
  group.add(backdrop);

  // --- Subtle grain overlay ---
  const grainMat = new MeshBasicNodeMaterial();
  grainMat.transparent = true;
  grainMat.opacity = 0.035;
  grainMat.depthWrite = false;
  const grainT = time.mul(12.0);
  const grainVal = smoothstep(0.45, 0.55, uv().x.add(uv().y).add(grainT.sin().mul(0.3)).fract());
  grainMat.colorNode = mix(vec3(0, 0, 0), vec3(1, 1, 1), grainVal);
  const grainPlane = new Mesh(new PlaneGeometry(7.2, 6.2), grainMat);
  grainPlane.position.set(0, 0, -2.49);
  group.add(grainPlane);

  // --- Main textured plane ---
  const planeMat = new MeshBasicNodeMaterial();
  planeMat.transparent = true;
  planeMat.opacity = 0;
  planeMat.toneMapped = true;

  const planeGeom = new PlaneGeometry(3.2, 2.0);
  const mainPlane = new Mesh(planeGeom, planeMat);
  mainPlane.position.set(0, 0, 0);
  group.add(mainPlane);

  // Load texture asynchronously
  const imageUrl = config.imageUrl ?? config.intent?.visualSpec?.imageUrl;
  if (imageUrl) {
    ctx.textureLoader.loadTexture(imageUrl).then((tex) => {
      tex.colorSpace = THREE.SRGBColorSpace;
      planeMat.map = tex;
      planeMat.needsUpdate = true;
    });
  }

  // --- Foreground accent frame (thin border to add depth plane) ---
  const frameMat = new MeshBasicNodeMaterial();
  frameMat.transparent = true;
  frameMat.opacity = 0.6;
  frameMat.colorNode = vec3(accent.r * 0.5, accent.g * 0.5, accent.b * 0.5);
  const frameGeom = new PlaneGeometry(3.3, 2.1);
  const frame = new Mesh(frameGeom, frameMat);
  frame.position.set(0, 0, -0.01);
  group.add(frame);

  // --- Contact shadow plane below ---
  const shadowMat = new MeshBasicNodeMaterial();
  shadowMat.transparent = true;
  shadowMat.opacity = 0.5;
  shadowMat.depthWrite = false;
  const shadowCol = uniform(vec3(0, 0, 0));
  const su = uv();
  const sDist = su.sub(0.5).length();
  const sAlpha = smoothstep(0.5, 0.0, sDist).oneMinus();
  shadowMat.colorNode = vec3(0, 0, 0);
  shadowMat.opacityNode = sAlpha.mul(0.5);
  const shadowPlane = new Mesh(new PlaneGeometry(4.0, 2.6), shadowMat);
  shadowPlane.position.set(0, -1.3, -0.02);
  shadowPlane.rotation.x = -Math.PI / 2.2;
  group.add(shadowPlane);

  // --- Entrance animation ---
  const tl = gsap.timeline();
  group.position.y = 0.4;
  group.userData._targetOpacity = 1;

  tl.to(group.position, {
    y: 0,
    duration: 0.7,
    ease: 'power3.out',
  });
  tl.to(planeMat, {
    opacity: 1,
    duration: 0.6,
    ease: 'power2.out',
  }, 0.1);
  tl.to(frameMat, {
    opacity: 0.15,
    duration: 0.5,
    ease: 'power2.out',
  }, 0.3);

  // --- Cleanup ---
  const cleanups = [];
  group.userData.cleanup = () => {
    tl.kill();
    planeGeom.dispose();
    frameGeom.dispose();
    backdropMat.dispose();
    grainMat.dispose();
    planeMat.dispose();
    frameMat.dispose();
    shadowMat.dispose();
    shadowPlane.geometry.dispose();
    backdrop.geometry.dispose();
    grainPlane.geometry.dispose();
    for (const c of cleanups) {
      try { c(); } catch (e) {}
    }
  };

  group.userData.handlers = {};

  return group;
}
